Execute 'FS-Filters.ipynb'. Save the results in html format in ../results. For all the runs, disable the cell execution timeout and allow errors.
Questions:
{
  "q1": "Report the best accuracy of the hybrid filter wrapper strategy.",
  "q2": "fig Report the name of the feature with the highest I-Gain."
}

arguments.command:
cd /code && python - <<'PY'
import nbformat, json
nb=nbformat.read('../results/FS-Filters-executed.ipynb', as_version=4)
for i,c in enumerate(nb.cells):
    if c.cell_type=='code' and c.outputs:
        print('\nCELL',i)
        for out in c.outputs:
            if out.output_type=='stream':
                txt=out.text
                if len(txt)>1000: txt=txt[:1000]
                print('STREAM:',txt)
            elif out.output_type=='execute_result':
                data=out.data
                if 'text/plain' in data:
                    txt=data['text/plain']
                    if isinstance(txt,list): txt=''.join(txt)
                    if len(txt)>1000: txt=txt[:1000]
                    print('RESULT:',txt)
            elif out.output_type=='display_data':
                data=out.data
                if 'text/plain' in data:
                    print('DISPLAY:', data['text/plain'])
PY
